/// The emoji for a shortcode alias (the text between the colons).
pub(crate) fn lookup(alias: &str) -> Option<&'static str> {
    let bytes = TABLE.as_bytes();
    let (mut low, mut high) = (0usize, bytes.len());
    while low < high {
        let mid = low + (high - low) / 2;
        // Snap to the start of the line containing `mid`. Newlines are ASCII,
        // so line bounds are always char boundaries even inside emoji bytes.
        let start = bytes[..mid]
            .iter()
            .rposition(|&byte| byte == b'\n')
            .map_or(0, |newline| newline + 1);
        let end = bytes[start..]
            .iter()
            .position(|&byte| byte == b'\n')
            .map_or(bytes.len(), |offset| start + offset);
        let (name, emoji) = TABLE[start..end].split_once('\t')?;
        match name.cmp(alias) {
            std::cmp::Ordering::Equal => return Some(emoji),
            std::cmp::Ordering::Less => low = end + 1,
            std::cmp::Ordering::Greater => high = start,
        }
    }
    None
}

#[cfg(test)]
mod tests {
    #[test]
    fn every_alias_round_trips_and_misses_are_none() {
        for line in super::TABLE.lines() {
            let (alias, emoji) = line.split_once('\t').unwrap_or_default();
            assert_eq!(super::lookup(alias), Some(emoji), "{alias}");
        }
        for miss in ["", "zzzz", "+0", "rocke", "rocketx", "ROCKET"] {
            assert_eq!(super::lookup(miss), None, "{miss}");
        }
    }
}
